INSERT INTO "categories" ("id", "name", "slug", "description", "image_url", "sort_order", "active", "created_at", "updated_at") VALUES
(1, 'Camisetas', 'camisetas', 'Algodón suave para el día a día: básicas, oversize y manga larga.', '/uploads/products/cat-camisetas.webp', 1, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(2, 'Camisas y blusas', 'camisas-y-blusas', 'Oxford, lino y satín para la oficina o una cena.', '/uploads/products/cat-camisas-y-blusas.webp', 2, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(3, 'Pantalones', 'pantalones', 'Chinos, cargo, palazzo y jeans con cortes que se mantienen.', '/uploads/products/cat-pantalones.webp', 3, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(4, 'Vestidos', 'vestidos', 'Midi, camiseros y cruzados para todo el año.', '/uploads/products/cat-vestidos.webp', 4, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(5, 'Faldas', 'faldas', 'Plisadas, lápiz y de mezclilla.', '/uploads/products/cat-faldas.webp', 5, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(6, 'Chaquetas', 'chaquetas', 'Capas ligeras para las mañanas frías y las tardes de lluvia.', '/uploads/products/cat-chaquetas.webp', 6, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(7, 'Sudaderas', 'sudaderas', 'French terry y felpa con capucha, cremallera o cuello redondo.', '/uploads/products/cat-sudaderas.webp', 7, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(8, 'Shorts', 'shorts', 'Chinos, deportivos y de mezclilla para el calor.', '/uploads/products/cat-shorts.webp', 8, true, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z');
INSERT INTO "products" ("id", "name", "slug", "description", "category_id", "size_guide_id", "base_price", "compare_at_price", "material", "care", "gender", "featured", "status", "created_by", "created_at", "updated_at") VALUES
(1, 'Camiseta Básica Pima', 'camiseta-basica-pima', 'La camiseta que usarás todas las semanas. Algodón pima de fibra larga, cuello redondo con ribete y costuras dobles en hombros y ruedo.', 1, 1, 129.00, NULL, '100 % algodón pima peinado, 180 g/m²', 'Lavar a máquina en agua fría con colores similares. No usar cloro. Secar a la sombra. Planchar a temperatura media.', 'UNISEX', true, 'ACTIVO', 3, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(2, 'Camiseta Oversize Lago', 'camiseta-oversize-lago', 'Corte holgado con hombro caído y largo extra. Tejido grueso que cae bien y no transparenta.', 1, 1, 149.00, NULL, '100 % algodón, tejido jersey 220 g/m²', 'Lavar a máquina en agua fría con colores similares. No usar cloro. Secar a la sombra. Planchar a temperatura media.', 'UNISEX', true, 'ACTIVO', 3, '2026-08-15T15:00:00.000Z', '2026-08-15T15:00:00.000Z'),
(3, 'Camiseta Cuello V Esencial', 'camiseta-cuello-v-esencial', 'Cuello en V de profundidad media y un toque de elastano para que conserve la forma después de cada lavado.', 1, 1, 119.00, NULL, '95 % algodón, 5 % elastano', 'Lavar a máquina en agua fría con colores similares. No usar cloro. Secar a la sombra. Planchar a temperatura media.', 'HOMBRE', false, 'ACTIVO', 3, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(4, 'Camiseta Rayas Marinera', 'camiseta-rayas-marinera', 'Rayas horizontales tejidas, no estampadas. Cuello barco y manga corta con un ligero vuelo.', 1, 1, 159.00, NULL, '100 % algodón orgánico', 'Lavar a máquina en agua fría con colores similares. No usar cloro. Secar a la sombra. Planchar a temperatura media.', 'MUJER', false, 'ACTIVO', 3, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(5, 'Camiseta Manga Larga Térmica', 'camiseta-manga-larga-termica', 'Tejido waffle que guarda el calor sin pesar. Ideal como primera capa en las mañanas frías del altiplano.', 1, 1, 169.00, NULL, '60 % algodón, 40 % poliéster, tejido waffle', 'Lavar a máquina en agua fría con colores similares. No usar cloro. Secar a la sombra. Planchar a temperatura media.', 'UNISEX', false, 'ACTIVO', 3, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
(6, 'Camisa Oxford Clásica', 'camisa-oxford-clasica', 'Cuello con botones, bolsillo en el pecho y ajuste regular. Funciona con jeans o con un chino de vestir.', 2, 1, 299.00, NULL, '100 % algodón Oxford', 'Lavar a máquina en agua fría con colores similares. No usar cloro. Secar a la sombra. Planchar a temperatura media.', 'HOMBRE', true, 'ACTIVO', 3, '2025-10-01T15:00:00.000Z', '2025-10-01T15:00:00.000Z'),
